package com.bank.flink.align;

import java.math.BigDecimal;

// A signal on an input channel: a normal record or a checkpoint barrier.
class Signal {
    private final boolean barrier;
    private final String accountId;
    private final BigDecimal amount;

    private Signal(boolean barrier, String accountId, BigDecimal amount) {
        this.barrier = barrier;
        this.accountId = accountId;
        this.amount = amount;
    }

    static Signal record(String accountId, BigDecimal amount) {
        return new Signal(false, accountId, amount);
    }

    static Signal barrier() {
        return new Signal(true, null, null);
    }

    boolean isBarrier() { return barrier; }
    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
}
