package com.bank.flink.align;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.Logger;

// A two-input operator that checkpoints in ALIGNED or UNALIGNED mode.
class CheckpointableOperator {
    private static final Logger log = Logger.getLogger(CheckpointableOperator.class.getName());

    enum Mode { ALIGNED, UNALIGNED }

    private final Mode mode;
    private final Set<String> barrieredInputs = new HashSet<>();
    private final List<Signal> inFlightBuffer = new ArrayList<>();
    private boolean snapshotted = false;
    private int bufferedWhileWaiting = 0;  // proxy for alignment wait
    private int snapshotInFlightSize = 0;  // in-flight records captured (unaligned)

    CheckpointableOperator(Mode mode) {
        this.mode = mode;
    }

    void onSignal(String inputName, Signal s) {
        if (s.isBarrier()) {
            barrieredInputs.add(inputName);
            if (mode == Mode.UNALIGNED && !snapshotted) {
                // Snapshot immediately on FIRST barrier, capture in-flight buffer.
                snapshotInFlightSize = inFlightBuffer.size();
                snapshotted = true;
                log.info(() -> "UNALIGNED snapshot on first barrier from " + inputName
                        + " capturing " + snapshotInFlightSize + " in-flight records");
            } else if (mode == Mode.ALIGNED && barrieredInputs.size() == 2) {
                // Only snapshot once BOTH barriers have arrived.
                snapshotted = true;
                log.info(() -> "ALIGNED snapshot after both barriers; waited on "
                        + bufferedWhileWaiting + " buffered fast-channel records");
            }
            return;
        }
        // Normal record.
        if (mode == Mode.ALIGNED && barrieredInputs.contains(inputName) && barrieredInputs.size() < 2) {
            // This channel already barriered but the other has not: must buffer (wait).
            bufferedWhileWaiting++;
            inFlightBuffer.add(s);
        } else if (mode == Mode.UNALIGNED && !snapshotted) {
            // In-flight buffer that would be captured if a barrier arrives now.
            inFlightBuffer.add(s);
        }
    }

    boolean isSnapshotted() { return snapshotted; }
    int getBufferedWhileWaiting() { return bufferedWhileWaiting; }
    int getSnapshotInFlightSize() { return snapshotInFlightSize; }
    Mode getMode() { return mode; }
}
