package com.bank.flink.align;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: fast channel barriers early and keeps sending; slow channel
// barriers late. Compare aligned (long wait) vs unaligned (fast, bigger snapshot).
public class AlignedVsUnalignedDemo {
    private static final Logger log = Logger.getLogger(AlignedVsUnalignedDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new AlignLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "=== ALIGNED mode (under backpressure) ===");
        run(new CheckpointableOperator(CheckpointableOperator.Mode.ALIGNED));

        log.info(() -> "=== UNALIGNED mode (under backpressure) ===");
        run(new CheckpointableOperator(CheckpointableOperator.Mode.UNALIGNED));
    }

    private static void run(CheckpointableOperator op) {
        // Fast "transaction" channel barriers early.
        op.onSignal("txn", Signal.record("SAV2001", new BigDecimal("100")));
        op.onSignal("txn", Signal.barrier());
        // Fast channel keeps flooding while slow channel's barrier is delayed.
        for (int i = 0; i < 5; i++) {
            op.onSignal("txn", Signal.record("SAV2001", new BigDecimal("10")));
        }
        // Slow "reference" channel finally barriers.
        op.onSignal("ref", Signal.record("CUR3001", new BigDecimal("500")));
        op.onSignal("ref", Signal.barrier());

        log.info(() -> op.getMode() + " snapshotted=" + op.isSnapshotted()
                + " alignmentBuffered=" + op.getBufferedWhileWaiting()
                + " inFlightCaptured=" + op.getSnapshotInFlightSize());
    }
}

// ─── Would be in AlignLogFormatter.java in a real project ───
class AlignLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
